    for _, a in ipairs(cfg.arrays) do
        if a.enabled then
            checked.arrays[#checked.arrays + 1] = a
        end
    end
    basic(C.schema, checked, '')
    assert(
        #checked.arrays > 0 and #cfg.channels == 1,
        '至少启用一台阵列，并配置唯一的公共原料子网'
    )
