-- Stopped-mode forms edit device bindings and settings.
local F = {}
F.__index = F
local tabs = {
    '预缓存纠缠流体配置',
    '约束场与蜂群配置',
    '观测阵列与传送节点配置',
    '下单 ME 接口配置',
}
local sides = { '下', '上', '北', '南', '西', '东' }
local fluidLabels =
    { enabled = '启用预缓存', low = '库存下限 L', high = '预缓存目标 L' }
local function find(list, key, value)
    for i, x in ipairs(list or {}) do
        if x[key] == value then
            return x, i
        end
    end
end

local function unique(list, prefix)
    local n = 1
    while find(list, 'id', prefix .. n) do
        n = n + 1
    end
    return prefix .. n
end

function F.new(ui, cfg, component, save)
    local self = setmetatable({
        ui = ui,
        cfg = cfg,
        component = component,
        save = save,
        tab = 1,
        pos = 1,
        offset = 1,
        selected = {},
        grade = 1,
        boxPage = 1,
        fluidIndex = 1,
        fluidPage = 1,
        fluidKey = 'low',
        message = '修改会自动暂存；按 S 校验并保存',
        schema = {},
    }, F)
    for _, f in ipairs(ui.C.schema) do
        self.schema[f.key] = f
    end
    self.feedDraft = ui.C.newRecord(self.schema.feeds.fields)
    self.feedDraft.id = '预缓存设备-1'
    if #cfg.channels == 0 then
        self:record('channels')
    end
    self.devices = ui.C.scan(component, cfg)
    self.fluidRows = {}
    if #cfg.beePools == 1 then
        for _, a in ipairs(cfg.arrays) do
            if a.beePool == '' then
                a.beePool = cfg.beePools[1].id
            end
        end
    end
    for _, m in ipairs(ui.M) do
        self.fluidRows[#self.fluidRows + 1] = find(cfg.bands, 'material', m.source)
            or {
                material = m.source,
                low = math.min(1000000, cfg.fieldLimit - 1),
                high = math.min(2000000, cfg.fieldLimit),
            }
    end
    return self
end

function F:changed()
    if self.save.draft then
        self.save.draft(self.cfg)
    end
    self.message = '修改已暂存；按 S 校验并保存后生效'
end

function F:record(section)
    local r = self.ui.C.newRecord(self.schema[section].fields)
    if r.id then
        r.id = unique(
            self.cfg[section],
            ({ channels = '公共原料子网', beePools = '蜂群池' })[section] .. '-'
        )
    end
    self.cfg[section][#self.cfg[section] + 1] = r
    if section == 'beePools' then
        r.boxes = { 1 }
    end
    if section == 'beePools' and #self.cfg.beePools == 1 then
        for _, a in ipairs(self.cfg.arrays) do
            if a.beePool == '' then
                a.beePool = r.id
            end
        end
    end
    return r
end

function F:inventory(id)
    return find(self.cfg.inventories, 'id', id)
end

function F:removeUnusedInventory(id)
    if not id then
        return
    end
    for _, a in ipairs(self.cfg.arrays) do
        if a.loadPort == id or a.unloadPort == id then
            return
        end
        for _, b in ipairs(a.beeBoxes) do
            if b.inventory == id then
                return
            end
        end
    end
    for _, f in ipairs(self.cfg.feeds) do
        if f.io == id then
            return
        end
        for _, c in ipairs(f.cells) do
            if c.inventory == id then
                return
            end
        end
    end
    local _, i = find(self.cfg.inventories, 'id', id)
    if i then
        table.remove(self.cfg.inventories, i)
    end
end

function F:position(inv, transposer, side)
    inv.transposer, inv.side = transposer, side
end

function F:newInventory(prefix)
    local x = { id = unique(self.cfg.inventories, prefix .. '-'), transposer = '', side = 0 }
    self.cfg.inventories[#self.cfg.inventories + 1] = x
    return x
end

function F:beePort(a, mode, create)
    local x = self:inventory(a[mode .. 'Port'])
    if not x and create then
        x = self:newInventory(
            mode == 'load' and '蜂群装载 ME-IO 端口' or '蜂群回收 ME-IO 端口'
        )
        a[mode .. 'Port'] = x.id
    end
    return x
end

function F:beeBox(a, number, create)
    local b = find(a.beeBoxes, 'box', number)
    if not b and create then
        local port = self:beePort(a, 'load')
        local inv = self:newInventory('蜂群箱')
        if port then
            inv.transposer = port.transposer
        end
        b = { box = number, inventory = inv.id }
        a.beeBoxes[#a.beeBoxes + 1] = b
        self:beePort(a, 'load', true)
        self:beePort(a, 'unload', true)
    end
    return b
end

function F:boxes(pool)
    local seen = {}
    for _, c in ipairs(pool.cells) do
        seen[c.box] = true
    end
    for _, box in ipairs(pool.boxes or {}) do
        seen[box] = true
    end
    if not pool.boxes and not next(seen) then
        seen[1] = true
    end
    local boxes = {}
    for box in pairs(seen) do
        boxes[#boxes + 1] = box
    end
    table.sort(boxes)
    return boxes
end

function F:feedPort(feed, create)
    if create and not find(self.cfg.feeds, 'id', feed.id) then
        self.cfg.feeds[#self.cfg.feeds + 1] = feed
    end
    local inv = self:inventory(feed.io)
    if not inv and create then
        inv = self:newInventory('主网流体转运 ME-IO 端口')
        feed.io = inv.id
    end
    return inv
end

function F:feeds()
    return #self.cfg.feeds > 0 and self.cfg.feeds or { self.feedDraft }
end

function F:at(transposer, side)
    if transposer ~= '' then
        for _, inv in ipairs(self.cfg.inventories) do
            if inv.transposer == transposer and inv.side == side then
                return inv
            end
        end
    end
end

function F:fluidPosition(material)
    for i, m in ipairs(self.ui.M) do
        if m.source == material then
            return math.floor((i - 1) / 10) + 1, (i - 1) % 10 + 1
        end
    end
end

function F:placeFeedCell(feed, cell)
    local drive, slot = self:fluidPosition(cell.material)
    local port = self:feedPort(feed, true)
    local side = feed['drive' .. drive .. 'Side']
    local old = cell.inventory
    local inv = self:at(port.transposer, side) or self:newInventory('流体驱动器')
    inv.transposer, inv.side = port.transposer, side
    cell.inventory = inv.id
    cell.slot = slot
    self:removeUnusedInventory(old)
end

function F:feedCell(feed, material, enabled)
    local cell, i = find(feed.cells, 'material', material)
    if enabled and not cell then
        cell = { material = material }
        self:placeFeedCell(feed, cell)
        feed.cells[#feed.cells + 1] = cell
    elseif not enabled and cell then
        table.remove(feed.cells, i)
        self:removeUnusedInventory(cell.inventory)
    end
    return cell
end

function F:objects()
    local out = {}
    local function add(kind, value, label, box)
        out[#out + 1] = { kind = kind, value = value, label = label, box = box }
    end
    if self.tab == 1 then
        add('generators', self.cfg.generators, '纠缠装置')
        for _, f in ipairs(self:feeds()) do
            add('feed', f, '预缓存设备')
        end
        add('fluids', self.fluidRows, '流体预缓存')
    elseif self.tab == 2 then
        add('field', self.cfg, '约束场')
        for i, p in ipairs(self.cfg.beePools) do
            add('pool', p, '蜂群池：' .. (p.name or tostring(i)))
            for _, box in ipairs(self:boxes(p)) do
                add('box', p, '  箱子：' .. box, box)
            end
        end
    elseif self.tab == 3 then
        for i, a in ipairs(self.cfg.arrays) do
            add('array', a, '阵列：' .. (a.name or tostring(i)))
        end
    else
        add('channel', self.cfg.channels[1], '公共原料子网')
    end
    return out
end

function F:object()
    local list = self:objects()
    self.pos = math.max(1, math.min(self.pos, math.max(1, #list)))
    return list[self.pos], list
end

function F:openTab(tab)
    self.tab = tab
    self.pos = 1
    self.offset = 1
    self.popup = nil
    self.selected = {}
    self.boxPage = 1
end

function F:field(label, target, key, kind, source, lo, hi)
    local section = ({ pool = 'beePools', array = 'arrays' })[(self:object() or {}).kind]
    return {
        label = label,
        kind = kind or 'text',
        source = source,
        lo = lo or 0,
        hi = hi or 9007199254740991,
        default = key == 'name' and section and self.ui:recordName(self.cfg, section, target)
            or nil,
        get = function()
            return target[key]
        end,
        set = function(v)
            if key == 'name' and v == '' then
                target[key] = nil
            else
                target[key] = v
            end
        end,
    }
end

function F:form(fluidIndex)
    local o = self:object()
    local rows = {}
    if not o then
        return rows
    end
    local x = o.value
    if o.kind == 'fluids' then
        x = self.fluidRows[fluidIndex or self.fluidIndex]
    end
    local function add(f)
        f.index = #rows + 1
        rows[#rows + 1] = f
        return f
    end
    local function title(t)
        add({ kind = 'heading', label = t })
    end
    local function field(label, target, key, kind, source, lo, hi)
        return add(self:field(label, target, key, kind, source, lo, hi))
    end
    local function action(label, run)
        add({ kind = 'action', label = label, run = run })
    end
    local function virtual(label, kind, get, set, source, lo, hi)
        return add({
            label = label,
            kind = kind,
            get = get,
            set = set,
            source = source,
            lo = lo or 0,
            hi = hi or 9007199254740991,
        })
    end
    if o.kind == 'field' then
        field('约束场设备', x, 'storage', 'choice', 'device:bec_storage')
        field('约束场强度 L', x, 'fieldLimit', 'number', nil, 1)
    elseif o.kind == 'fluids' then
        title(self.ui.M.name(x.material))
        virtual(fluidLabels.enabled, 'boolean', function()
            return find(self.cfg.bands, 'material', x.material) ~= nil
        end, function(v)
            local _, i = find(self.cfg.bands, 'material', x.material)
            if v and not i then
                self.cfg.bands[#self.cfg.bands + 1] = x
            elseif not v and i then
                table.remove(self.cfg.bands, i)
            end
            self:feedCell(self:feeds()[1], x.material, v)
        end)
        for _, spec in ipairs({ { fluidLabels.low, 'low', 0 }, { fluidLabels.high, 'high', 1 } }) do
            field(spec[1], x, spec[2], 'number', nil, spec[3])
        end
    elseif o.kind == 'generators' then
        local available = {}
        for _, d in ipairs(self.devices) do
            if self.ui.C.matches(d, 'generator') then
                available[#available + 1] = { address = d.address }
            end
        end
        for _, g in ipairs(self.cfg.generators) do
            if not find(available, 'address', g.address) then
                available[#available + 1] = { address = g.address, offline = true }
            end
        end
        for _, d in ipairs(available) do
            local address = d.address
            virtual(
                '启用 ' .. address:sub(1, 12) .. (d.offline and '（离线）' or ''),
                'boolean',
                function()
                    return find(self.cfg.generators, 'address', address) ~= nil
                end,
                function(v)
                    local _, i = find(self.cfg.generators, 'address', address)
                    if v and not i then
                        local feed = self:feeds()[1]
                        self:feedPort(feed, true)
                        self.cfg.generators[#self.cfg.generators + 1] =
                            { address = address, feed = feed.id }
                    elseif not v and i then
                        table.remove(self.cfg.generators, i)
                    end
                end
            )
        end
    elseif o.kind == 'pool' then
        field('蜂群池名称', x, 'name', 'text')
        action('新增箱子', function()
            local boxes = self:boxes(x)
            local box = 1
            for _, number in ipairs(boxes) do
                if number == box then
                    box = box + 1
                end
            end
            boxes[#boxes + 1] = box
            table.sort(boxes)
            x.boxes = boxes
            self:changed()
        end)
        title('选择左侧箱子，批量登记槽位和等级')
    elseif o.kind == 'array' then
        title('阵列与设备绑定')
        field('阵列名称', x, 'name', 'text')
        field('启用阵列', x, 'enabled', 'boolean')
        action('关联的传送节点：' .. #x.nodes .. ' 个', function()
            self:nodePicker(x)
        end)
        action('绑定未分配节点', function()
            self:bindNodes(x)
        end)
        action(
            '麦克斯韦门：' .. (x.diode ~= '' and x.diode:sub(1, 12) or '未绑定'),
            function()
                self:doorPicker(x)
            end
        )
        title('全局加工设置（所有阵列共用）')
        field(
            '算力奇点等待阈值（秒）',
            self.cfg,
            'singularityWait',
            'number',
            nil,
            1,
            2147483647
        )
        title('蜂群装载配置')
        field('使用的蜂群池', x, 'beePool', 'choice', 'beePools')
        local pool = find(self.cfg.beePools, 'id', x.beePool)
        if pool then
            local function common(mode, key)
                return function()
                    local p = self:beePort(x, mode)
                    return p and p[key] or (key == 'side' and 0 or '')
                end
            end
            virtual('蜂群转运器', 'choice', common('load', 'transposer'), function(v)
                for _, mode in ipairs({ 'load', 'unload' }) do
                    self:beePort(x, mode, true).transposer = v
                end
                for _, box in ipairs(self:boxes(pool)) do
                    local b = self:beeBox(x, box, true)
                    self:inventory(b.inventory).transposer = v
                end
            end, 'device:transposer')
            for _, spec in ipairs({ { 'load', '装载' }, { 'unload', '回收' } }) do
                local mode = spec[1]
                virtual(spec[2] .. ' ME-IO 端口方向', 'side', common(mode, 'side'), function(v)
                    self:beePort(x, mode, true).side = v
                end)
            end
            local boxes = self:boxes(pool)
            local configured = {}
            for _, box in ipairs(boxes) do
                configured[box] = true
            end
            for _, b in ipairs(x.beeBoxes) do
                if not configured[b.box] then
                    boxes[#boxes + 1] = b.box
                end
            end
            for _, box in ipairs(boxes) do
                if not configured[box] then
                    action('移除未登记的箱子 ' .. box .. ' 连接', function()
                        local b, i = find(x.beeBoxes, 'box', box)
                        table.remove(x.beeBoxes, i)
                        self:removeUnusedInventory(b.inventory)
                        self:changed()
                    end)
                end
                virtual('箱子 ' .. box .. ' 的方向', 'side', function()
                    local b = self:beeBox(x, box)
                    local inv = b and self:inventory(b.inventory)
                    return inv and inv.side or 0
                end, function(v)
                    local b = self:beeBox(x, box, true)
                    self:inventory(b.inventory).side = v
                end)
            end
        end
    elseif o.kind == 'channel' then
        title('主网下单接口')
        action('主网样板 ME 接口：' .. #x.patterns .. ' 个', function()
            self:patternPicker(x)
        end)
        for _, p in ipairs(x.patterns) do
            field(p.address:sub(1, 12) .. ' 样板槽数', p, 'slots', 'number', nil, 1, 128)
        end
        title('公共原料子网与共用锁单')
        field('公共原料子网 ME 控制器', x, 'buffer', 'choice', 'device:buffer')
        field('共用接单红石 I/O', x, 'redstone', 'choice', 'device:redstone')
        field('红石输出方向', x, 'gateSide', 'side')
    elseif o.kind == 'feed' then
        title('预缓存共用设备')
        virtual('流体转运器', 'choice', function()
            local p = self:feedPort(x)
            return p and p.transposer or ''
        end, function(v)
            local p = self:feedPort(x, true)
            self:position(p, v, p.side)
            for _, cell in ipairs(x.cells) do
                self:inventory(cell.inventory).transposer = v
            end
        end, 'device:transposer')
        virtual('主网流体转运 ME-IO 端口方向', 'side', function()
            local p = self:feedPort(x)
            return p and p.side or 0
        end, function(v)
            local p = self:feedPort(x, true)
            self:position(p, p.transposer, v)
        end)
        for drive = 1, 2 do
            local key = 'drive' .. drive .. 'Side'
            virtual(
                (drive == 1 and '第一台' or '第二台') .. '流体驱动器方向',
                'side',
                function()
                    return x[key]
                end,
                function(v)
                    x[key] = v
                    for _, cell in ipairs(x.cells) do
                        if self:fluidPosition(cell.material) == drive then
                            self:placeFeedCell(x, cell)
                        end
                    end
                end
            )
        end
        title('按流体表顺序放置：第一台 1～10，第二台 1～9')
    end
    return rows
end

function F:choices(f)
    local rows = self.ui:choices(f, self.cfg, self.devices)
    if f.source == 'device:buffer' then
        local controllers = {}
        for _, row in ipairs(rows) do
            if self.component.type(row.value) == 'me_controller' then
                controllers[#controllers + 1] = row
            end
        end
        rows = controllers
    end
    return rows
end

function F:nodePicker(a)
    local allowed = {}
    for _, d in ipairs(self.ui.C.unboundNodes(self.cfg, self.devices)) do
        allowed[d.address] = true
    end
    local checked = {}
    for _, n in ipairs(a.nodes) do
        checked[n.address] = true
        allowed[n.address] = true
    end
    local options, visible = {}, {}
    for _, d in ipairs(self.devices) do
        if allowed[d.address] then
            options[#options + 1] = { value = d.address, label = d.address }
            visible[d.address] = true
        end
    end
    for _, n in ipairs(a.nodes) do
        if not visible[n.address] then
            options[#options + 1] = { value = n.address, label = n.address .. '（离线）' }
        end
    end
    self.popup = {
        title = '关联的传送节点',
        options = options,
        checked = checked,
        page = 1,
        all = true,
        reopen = function()
            self:nodePicker(a)
        end,
        apply = function(values)
            assert(#values <= 16, '每台阵列最多关联 16 个传送节点')
            local want = {}
            for _, v in ipairs(values) do
                want[v] = true
            end
            local result = {}
            for _, n in ipairs(a.nodes) do
                if want[n.address] then
                    result[#result + 1] = n
                    want[n.address] = nil
                end
            end
            for _, v in ipairs(values) do
                if want[v] then
                    result[#result + 1] = { address = v }
                end
            end
            a.nodes = result
        end,
    }
end

function F:bindNodes(a)
    self.devices = self.ui.C.scan(self.component, self.cfg)
    local count = #a.nodes
    local ok, message = self.ui.C.bindNodes(self.cfg, a, self.devices)
    if not ok then
        self:nodePicker(a)
    elseif #a.nodes ~= count then
        self:changed()
    end
    self.message = message
end

function F:doorPicker(a)
    self.devices = self.ui.C.scan(self.component, self.cfg)
    local options = {}
    for _, d in ipairs(self.ui.C.unboundDoors(self.cfg, self.devices)) do
        options[#options + 1] = { value = d.address, label = d.address }
    end
    if #options == 1 then
        a.diode = options[1].value
        self:changed()
        return
    end
    self.popup = {
        title = '未分配的麦克斯韦门',
        options = options,
        page = 1,
        reopen = function()
            self:doorPicker(a)
        end,
        choose = function(v)
            a.diode = v
        end,
    }
end

function F:patternPicker(c)
    local options = {}
    for _, d in ipairs(self.devices) do
        if self.ui.C.matches(d, 'pattern') then
            options[#options + 1] = { value = d.address, label = d.address }
        end
    end
    local checked = {}
    for _, p in ipairs(c.patterns) do
        checked[p.address] = true
        if not find(options, 'value', p.address) then
            options[#options + 1] = { value = p.address, label = p.address .. '（离线）' }
        end
    end
    self.popup = {
        title = '主网样板 ME 接口',
        options = options,
        checked = checked,
        page = 1,
        reopen = function()
            self:patternPicker(c)
        end,
        apply = function(values)
            local want = {}
            for _, v in ipairs(values) do
                want[v] = true
            end
            local result = {}
            for _, p in ipairs(c.patterns) do
                if want[p.address] then
                    result[#result + 1] = p
                    want[p.address] = nil
                end
            end
            for _, v in ipairs(values) do
                if want[v] then
                    result[#result + 1] = { address = v, slots = 36 }
                end
            end
            c.patterns = result
        end,
    }
end
function F:fluidField(index, key, rows)
    for _, f in ipairs(rows or self:form(index)) do
        if f.label == fluidLabels[key] then
            f.fluid = index
            f.key = key
            return f
        end
    end
end

function F:begin(f)
    self.edit = {
        field = f,
        text = f.kind == 'number' and self.ui.exact(f.get()) or tostring(f.get() or ''),
        replace = true,
    }
end

function F:commit()
    local e = self.edit
    if not e then
        return true
    end
    local v = e.text
    local f = e.field
    if f.kind == 'number' then
        v = tonumber(v)
        if not self.save.U.integer(v, f.lo, f.hi) then
            self.message = '请输入 ' .. f.lo .. ' 至 ' .. f.hi .. ' 的整数'
            return false
        end
    end
    self.edit = nil
    if f.get() ~= v then
        f.set(v)
        self:changed()
    end
    return true
end

function F:activate(f, button)
    if button ~= nil and f.kind == 'side' then
        f.set((f.get() + (button == 1 and -1 or 1)) % 6)
        self:changed()
    elseif f.kind == 'action' then
        f.run()
    elseif f.kind == 'boolean' then
        f.set(not f.get())
        self:changed()
    elseif f.kind == 'choice' or f.kind == 'side' then
        local options = f.kind == 'side' and {} or self:choices(f)
        if f.kind == 'side' then
            for i = 0, 5 do
                options[#options + 1] = { value = i, label = i .. ' ' .. sides[i + 1] }
            end
        end
        self.popup = {
            title = f.label,
            empty = f.source == 'beePools'
                and '请先在第 2 页“约束场与蜂群配置”中新增蜂群池',
            options = options,
            page = 1,
            current = f.get(),
            reopen = function()
                self:activate(f)
            end,
            choose = function(v)
                f.set(v)
            end,
        }
    elseif f.kind ~= 'heading' then
        self:begin(f)
    end
end

function F:act(action, button)
    if not action then
        return
    end
    if
        self.popup
        and self.popup.clearRecipes
        and action ~= 'back'
        and action ~= 'quit'
        and not action:match('^pick:')
    then
        return
    end
    if action == 'quit' then
        self.edit = nil
        self.done = true
        return
    end
    if action == 'back' then
        if self.edit then
            self.edit = nil
        elseif self.popup then
            self.popup = nil
        else
            self.done = true
        end
        return
    end
    if action == 'cancel-edit' then
        self.edit = nil
        self.message = '已取消本次输入'
        return
    end
    if action:match('^fluid%-preset:') then
        local f = self:fluidField(self.fluidIndex, self.fluidKey)
        if f and (self.fluidKey == 'low' or self.fluidKey == 'high') then
            f.set(tonumber(action:match(':(.+)$')))
            self.edit = nil
            self:changed()
        end
        return
    end
    if action:match('^fluid%-scale:') then
        local f = self:fluidField(self.fluidIndex, self.fluidKey)
        if f and (self.fluidKey == 'low' or self.fluidKey == 'high') then
            if not self:commit() then
                return
            end
            local value = math.floor(f.get() * tonumber(action:match(':(.+)$')))
            if not self.save.U.integer(value, f.lo, f.hi) then
                self.message = '结果须为 ' .. f.lo .. ' 至 ' .. f.hi .. ' 的整数'
                return
            end
            f.set(value)
            self:changed()
        end
        return
    end
    if not self:commit() then
        return
    end
    local o = self:object()
    if action == 'clear-recipes' then
        self.popup = {
            title = '清除全部配方加工记录？',
            clearRecipes = true,
            page = 1,
            current = false,
            options = {
                {
                    value = false,
                    label = '取消，保留记录',
                    detail = '保留已记录的流体需求和加工阶段',
                },
                {
                    value = true,
                    label = '确认清除全部配方加工记录',
                    detail = '仅清除加工信息，下次取料时重新记录',
                },
            },
        }
    elseif action:match('^tab:') then
        self:openTab(tonumber(action:sub(5)))
    elseif action:match('^select:') then
        self.pos = tonumber(action:sub(8))
        self.offset = 1
        self.selected = {}
        self.boxPage = 1
        self.popup = nil
    elseif action:match('^field:') then
        self:activate(self:form()[tonumber(action:sub(7))], button)
    elseif action:match('^fluid:') then
        local index, key = action:match('^fluid:(%d+):(%w+)$')
        self.fluidIndex, self.fluidKey = tonumber(index), key
        if key ~= 'name' then
            local f = self:fluidField(self.fluidIndex, key)
            if f then
                self:activate(f, button)
            end
        end
    elseif action == 'save' then
        local ok, err = pcall(function()
            for _, band in ipairs(self.cfg.bands) do
                self:feedCell(self:feeds()[1], band.material, true)
            end
            for _, feed in ipairs(self.cfg.feeds) do
                for _, cell in ipairs(feed.cells) do
                    self:placeFeedCell(feed, cell)
                end
            end
            self.ui.C.validate(self.cfg, self.component, self.save.U)
            self.save.write(self.cfg)
        end)
        if ok then
            self.saved = true
            self.done = true
        else
            self.message = tostring(err):gsub('^.-:%d+: ', '')
        end
    elseif action == 'refresh' then
        local count = #self.cfg.arrays
        self.devices = self.ui.C.scan(self.component, self.cfg)
        local popup = self.popup
        if popup and popup.reopen then
            self.popup = nil
            popup.reopen()
            if self.popup and self.popup.checked and popup.checked then
                for address, checked in pairs(popup.checked) do
                    self.popup.checked[address] = checked
                end
            end
        end
        if #self.cfg.arrays ~= count then
            self:changed()
        end
        self.message = '设备列表已刷新'
    elseif action == 'add' then
        if self.tab == 2 then
            self:record('beePools')
            self:changed()
        end
    elseif action == 'delete' and o then
        if o.kind == 'box' then
            local pool = o.value
            pool.boxes = self:boxes(pool)
            for i = #pool.cells, 1, -1 do
                if pool.cells[i].box == o.box then
                    table.remove(pool.cells, i)
                end
            end
            for i, box in ipairs(pool.boxes) do
                if box == o.box then
                    table.remove(pool.boxes, i)
                    break
                end
            end
            for _, a in ipairs(self.cfg.arrays) do
                if a.beePool == pool.id then
                    for i = #a.beeBoxes, 1, -1 do
                        local box = a.beeBoxes[i]
                        if box.box == o.box then
                            table.remove(a.beeBoxes, i)
                            self:removeUnusedInventory(box.inventory)
                        end
                    end
                end
            end
            self.selected = {}
            self.boxPage, self.offset = 1, 1
            for i, item in ipairs(self:objects()) do
                if item.kind == 'pool' and item.value == pool then
                    self.pos = i
                    break
                end
            end
            self:changed()
            return
        end
        local section = o.kind == 'pool' and 'beePools'
        if section then
            for i, v in ipairs(self.cfg[section]) do
                if v == o.value then
                    table.remove(self.cfg[section], i)
                    break
                end
            end
            self:changed()
        end
    elseif action == 'up' or action == 'down' then
        if self.popup then
            self:act(action == 'up' and 'prev' or 'next')
        else
            self.pos = math.max(1, self.pos + (action == 'up' and -1 or 1))
            self.offset = 1
            self.selected = {}
        end
    elseif action == 'prev' or action == 'next' then
        if self.popup then
            self.popup.page = math.max(
                1,
                math.min(self.optionPages or 1, self.popup.page + (action == 'prev' and -1 or 1))
            )
        elseif o and o.kind == 'fluids' then
            self.fluidPage = math.max(
                1,
                math.min(self.fluidPages or 1, self.fluidPage + (action == 'prev' and -1 or 1))
            )
        elseif o and o.kind == 'box' then
            self.boxPage = math.max(1, self.boxPage + (action == 'prev' and -1 or 1))
            self.selected = {}
        else
            self.offset = math.max(
                1,
                math.min(
                    math.max(1, #self:form()),
                    self.offset + (action == 'prev' and -1 or 1) * (self.perPage or 7)
                )
            )
        end
    elseif action:match('^pick:') and self.popup then
        local p = self.popup
        local option = p.options[tonumber(action:sub(6))]
        if p.clearRecipes then
            self.popup = nil
            if option.value then
                local ok, result = pcall(self.save.clearRecipes)
                self.message = ok
                        and ('已清除 ' .. result .. ' 条配方加工记录，已保存')
                    or tostring(result):gsub('^.-:%d+: ', '')
            else
                self.message = '已取消清除，配方加工记录保持不变'
            end
        elseif p.checked then
            p.checked[option.value] = not p.checked[option.value]
        else
            p.choose(option.value)
            self.popup = nil
            self:changed()
        end
    elseif action == 'all' and self.popup then
        for _, v in ipairs(self.popup.options) do
            self.popup.checked[v.value] = true
        end
    elseif action == 'apply' and self.popup then
        local p = self.popup
        local values = {}
        for _, v in ipairs(p.options) do
            if p.checked[v.value] then
                values[#values + 1] = v.value
            end
        end
        local ok, err = pcall(p.apply, values)
        if ok then
            self.popup = nil
            self:changed()
        else
            self.message = tostring(err):gsub('^.-:%d+: ', '')
        end
    elseif action:match('^slot:') then
        local n = tonumber(action:sub(6))
        self.selected[n] = not self.selected[n]
    elseif action == 'grade-' or action == 'grade+' then
        self.grade = math.max(1, math.min(10, self.grade + (action == 'grade-' and -1 or 1)))
    elseif (action == 'register' or action == 'unregister') and o and o.kind == 'box' then
        o.value.boxes = self:boxes(o.value)
        for slot, selected in pairs(self.selected) do
            if selected then
                local cell, index
                for i, c in ipairs(o.value.cells) do
                    if c.box == o.box and c.slot == slot then
                        cell, index = c, i
                        break
                    end
                end
                if action == 'unregister' then
                    if index then
                        table.remove(o.value.cells, index)
                    end
                elseif cell then
                    cell.tier = self.grade
                else
                    o.value.cells[#o.value.cells + 1] =
                        { box = o.box, slot = slot, tier = self.grade }
                end
            end
        end
        self.selected = {}
        self:changed()
    elseif action == 'open' then
        local f = self:form()[self.offset]
        if f then
            self:activate(f)
        end
    end
end

function F:event(name, _, ch, code, direction)
    if name == 'interrupted' then
        self:act('quit')
        return
    end
    if name == 'touch' then
        self:act(self.ui:hit(ch, code), direction or 0)
        return
    end
    if self.edit then
        local e = self.edit
        if name == 'clipboard' then
            e.text = tostring(ch):gsub('[\r\n]', '')
            e.replace = false
        elseif name == 'key_down' then
            if code == 28 then
                self:commit()
            elseif code == 14 then
                e.text = self.ui.u.sub(e.text, 1, math.max(0, self.ui.u.len(e.text) - 1))
                e.replace = false
            elseif ch == 21 then
                e.text = ''
                e.replace = false
            elseif ch and ch >= 32 then
                e.text = (e.replace and '' or e.text) .. self.ui.u.char(ch)
                e.replace = false
            end
        end
        return
    end
    if name == 'scroll' then
        local objects = not self.popup and ch <= (self.left or 20)
        self:act(direction > 0 and (objects and 'up' or 'prev') or (objects and 'down' or 'next'))
    elseif name == 'key_down' then
        if ch == 115 or ch == 83 then
            self:act('save')
        elseif ch == 113 or ch == 81 then
            self:act('quit')
        elseif ch == 102 or ch == 70 then
            self:act('refresh')
        elseif ch == 97 or ch == 65 then
            self:act('add')
        elseif ch == 100 or ch == 68 then
            self:act('delete')
        elseif ch and ch >= 49 and ch <= 52 then
            self:act('tab:' .. (ch - 48))
        elseif code == 28 then
            self:act('open')
        elseif code == 200 then
            self:act('up')
        elseif code == 208 then
            self:act('down')
        elseif code == 201 or ch == 91 then
            self:act('prev')
        elseif code == 209 or ch == 93 then
            self:act('next')
        end
    end
end

function F:value(f)
    local v = f.get()
    if f.kind == 'boolean' then
        return v and '是' or '否'
    end
    if f.kind == 'side' then
        return tostring(v) .. ' ' .. (sides[(v or 0) + 1] or '')
    end
    if f.kind == 'choice' and f.source and not f.source:match('^device:') then
        return self.ui:recordName(self.cfg, f.source, v)
    end
    if v == nil or v == '' then
        return f.default or '未选择'
    end
    return type(v) == 'number' and self.ui.exact(v) or tostring(v)
end

function F:drawBox(o, x, width)
    local ui = self.ui
    local cells = {}
    for _, c in ipairs(o.value.cells) do
        if c.box == o.box then
            cells[c.slot] = c.tier
        end
    end
    ui:put(x, 6, '箱子 ' .. o.box .. ' / 按槽位登记蜂群', width, ui.ink.green)
    local cw = math.floor(width / 9)
    local first = (self.boxPage - 1) * 27 + 1
    for i = 0, 26 do
        local slot = first + i
        local xx = x + (i % 9) * cw
        local yy = 8 + math.floor(i / 9) * 3
        ui:control('slot:' .. slot, xx, yy, tostring(slot), self.selected[slot], cw)
        if not self.selected[slot] then
            ui:put(
                xx,
                yy,
                tostring(slot),
                cw,
                cells[slot] and ui.ink.green or ui.ink.dim,
                ui.ink.panel
            )
        end
        ui:put(
            xx + 1,
            yy + 1,
            cells[slot] and 'T' .. cells[slot] or '--',
            cw - 1,
            cells[slot] and ui.ink.green or ui.ink.dim
        )
    end
    local gradeY, registerY = math.min(17, ui.h - 9), math.min(19, ui.h - 8)
    ui:control('grade-', x, gradeY, '-')
    ui:put(x + 5, gradeY, 'T' .. self.grade, 5, ui.ink.cyan)
    ui:control('grade+', x + 11, gradeY, '+')
    ui:control('register', x, registerY, '登记所选')
    ui:control('unregister', x + 14, registerY, '取消登记')
    local counts = {}
    for _, tier in pairs(cells) do
        counts[tier] = (counts[tier] or 0) + 1
    end
    local summary = {}
    for tier = 1, 10 do
        if counts[tier] then
            summary[#summary + 1] = 'T' .. tier .. '×' .. counts[tier]
        end
    end
    ui:put(x, 7, '青底：已选  绿色：已登记  --：未登记', width, ui.ink.dim)
    ui:put(x, ui.h - 4, table.concat(summary, ' '), width, ui.ink.dim)
end

function F:drawFluids(x, width, b)
    local ui, ink = self.ui, self.ui.ink
    local numberWidth = width >= 80 and 10 or 7
    local widths =
        { 6, math.min(24, width - 6 - numberWidth * 2 - 7 - 4), numberWidth, numberWidth, 7 }
    local keys = { 'enabled', 'name', 'low', 'high', 'position' }
    local labels = { '预缓存', '流体', '下限 L', '目标 L', '位置' }
    local positions = {}
    local px = x
    for i, key in ipairs(keys) do
        positions[key] = px
        ui:put(px, b.top, labels[i], widths[i], ink.dim)
        px = px + widths[i] + 1
    end
    local editTop = b.bottom - 6
    local per = math.max(1, editTop - b.top - 1)
    self.fluidPages = math.max(1, math.ceil(#self.fluidRows / per))
    self.fluidPage = math.min(self.fluidPage, self.fluidPages)
    local first = (self.fluidPage - 1) * per + 1
    local function short(n)
        for _, unit in ipairs({ { 1e9, 'G' }, { 1e6, 'M' }, { 1e3, 'K' } }) do
            if n >= unit[1] then
                return string.format('%.3g%s', n / unit[1], unit[2])
            end
        end
        return ui.exact(n)
    end
    for index = first, math.min(#self.fluidRows, first + per - 1) do
        local row = self.fluidRows[index]
        local y = b.top + 1 + index - first
        local fields = self:form(index)
        for col, key in ipairs(keys) do
            local f = key ~= 'name' and self:fluidField(index, key, fields)
            local value = key == 'name' and ui.M.name(row.material, true) or '--'
            if key == 'position' then
                local drive, slot = self:fluidPosition(row.material)
                value = drive .. '/' .. slot
            end
            if f then
                local v = f.get()
                value = (key == 'low' or key == 'high') and short(v) or (v and '启用' or '关闭')
            end
            if key == 'name' or f then
                local selected = index == self.fluidIndex and key == self.fluidKey
                ui:control(
                    'fluid:' .. index .. ':' .. key,
                    positions[key],
                    y,
                    value,
                    selected,
                    widths[col]
                )
                if key == 'enabled' and not selected then
                    ui:put(
                        positions[key],
                        y,
                        value,
                        widths[col],
                        f.get() and ink.green or ink.dim,
                        ink.panel
                    )
                end
            else
                ui:put(positions[key], y, value, widths[col], ink.dim)
            end
        end
    end
    ui:put(x, editTop, string.rep('─', width), width, ink.dim)
    local row = self.fluidRows[self.fluidIndex]
    local f = self:fluidField(self.fluidIndex, self.fluidKey)
    ui:put(x, editTop + 1, ui.M.name(row.material), width, ink.green)
    if f then
        local editing = self.edit
            and self.edit.field.fluid == self.fluidIndex
            and self.edit.field.key == self.fluidKey
        local labelWidth = math.min(22, math.floor(width / 2))
        ui:put(x, editTop + 2, f.label, labelWidth, ink.text)
        ui:control(
            'fluid:' .. self.fluidIndex .. ':' .. self.fluidKey,
            x + labelWidth,
            editTop + 2,
            editing and self.edit.text .. '_' or self:value(f),
            editing,
            width - labelWidth
        )
        if self.fluidKey == 'low' or self.fluidKey == 'high' then
            local step = 8
            for i, preset in ipairs({
                { '1M', 1e6 },
                { '10M', 1e7 },
                { '100M', 1e8 },
                { '1G', 1e9 },
                {
                    '10G',
                    1e10,
                },
            }) do
                ui:control(
                    'fluid-preset:' .. ui.exact(preset[2]),
                    x + (i - 1) * step,
                    editTop + 3,
                    preset[1],
                    false,
                    step - 1
                )
            end
            for i, scale in ipairs({ { '÷2', 0.5 }, { '÷5', 0.2 }, { '×2', 2 }, { '×5', 5 } }) do
                ui:control(
                    'fluid-scale:' .. scale[2],
                    x + (i - 1) * step,
                    editTop + 4,
                    scale[1],
                    false,
                    step - 1
                )
            end
        end
        if editing then
            ui:control('confirm-edit', x, editTop + 5, '确认')
            ui:control('cancel-edit', x + 10, editTop + 5, '取消')
            ui:put(x + 20, editTop + 5, 'Enter 确认', width - 20, ink.dim)
        end
    else
        ui:put(x, editTop + 2, '点击表格中的值修改配置', width, ink.dim)
    end
    ui:put(
        x,
        b.status,
        '位置：驱动器编号/固定槽位；关闭后保留位置',
        width,
        ink.dim
    )
end

function F:draw()
    local ui = self.ui
    local ink = ui.ink
    ui:begin('BEC / 多观测阵列配置')
    local w, h = ui.w, ui.h
    local left = w >= 120 and 30 or 20
    local x = left + 3
    local width = w - x - 1
    self.left = left
    local b = { top = 6, bottom = h - 7, status = h - 6, nav = h - 5 }
    local tabWidth = 0
    for i, t in ipairs(tabs) do
        tabWidth = tabWidth + ui.u.wlen(i .. ' ' .. t) + 3
    end
    local tx = 2
    for i, t in ipairs(tabs) do
        if tabWidth <= w - 2 then
            local tw = ui.u.wlen(i .. ' ' .. t) + 2
            ui:control('tab:' .. i, tx, 3, i .. ' ' .. t, self.tab == i, tw)
            tx = tx + tw + 1
        else
            ui:control(
                'tab:' .. i,
                2 + ((i - 1) % 2) * math.floor(w / 2),
                3 + math.floor((i - 1) / 2),
                i .. ' ' .. t,
                self.tab == i,
                math.floor(w / 2) - 2
            )
        end
    end
    ui:frame(1, 5, left + 1, h - 7)
    ui:frame(x - 1, 5, width + 2, h - 7)
    local o, list = self:object()
    local menu = {}
    local selectedLine = 1
    for i, v in ipairs(list) do
        if i > 1 and (v.kind == 'fluids' or v.kind == 'pool') then
            menu[#menu + 1] = false
        end
        menu[#menu + 1] = i
        if i == self.pos then
            selectedLine = #menu
        end
        if v.kind == 'array' then
            menu[#menu + 1] = { nodes = #v.value.nodes }
        end
    end
    local leftPer = self.tab == 3 and math.floor((h - 13) / 2) * 2 or h - 13
    local first = math.floor((selectedLine - 1) / leftPer) * leftPer + 1
    for line = first, math.min(#menu, first + leftPer - 1) do
        local i = menu[line]
        if type(i) == 'table' then
            ui:put(
                3,
                b.top + line - first,
                '关联节点 ' .. i.nodes .. ' / 16',
                left - 2,
                ink.dim
            )
        elseif i then
            ui:control(
                'select:' .. i,
                2,
                b.top + line - first,
                list[i].label,
                i == self.pos,
                left - 1
            )
        end
    end
    ui:put(2, h - 6, '对象 ' .. self.pos .. '/' .. #list, left, ink.dim)
    ui:control('up', 2, h - 5, '上一个')
    ui:control('down', 12, h - 5, '下一个', false, left - 10)
    if self.tab == 2 then
        ui:control('add', 2, h - 4, '新增蜂群池', false, left)
    elseif self.tab == 4 then
        ui:control('clear-recipes', 2, h - 4, '清除配方记录', false, left)
    end
    if o and (o.kind == 'pool' or o.kind == 'box') then
        ui:control('delete', 2, h - 3, o.kind == 'box' and '删除箱子' or '删除蜂群池')
    end
    local stride = w >= 120 and 1 or 2
    self.perPage = math.max(1, math.floor((h - 13) / stride))
    if self.popup then
        local p = self.popup
        local step = p.clearRecipes and 3 or (p.options[1] and p.options[1].detail and 2 or 1)
        local per = math.floor((h - 15) / step)
        self.optionPages = math.max(1, math.ceil(#p.options / per))
        p.page = math.min(p.page, self.optionPages)
        ui:put(x, 6, p.title, width, ink.green)
        local start = (p.page - 1) * per + 1
        for i = start, math.min(#p.options, start + per - 1) do
            local v = p.options[i]
            local y = 8 + (i - start) * step
            ui:control(
                'pick:' .. i,
                x,
                y,
                (p.checked and (p.checked[v.value] and '[x] ' or '[ ] ') or '') .. v.label,
                p.current == v.value,
                width
            )
            if step >= 2 then
                local indent = p.clearRecipes and 4 or 0
                ui:put(
                    x + indent,
                    y + 1,
                    v.detail or '',
                    width - indent,
                    p.clearRecipes and 0x999999 or ink.dim
                )
            end
        end
        if #p.options == 0 then
            ui:wrap(x, 8, p.empty or '没有可选设备；按 F 刷新', width, 2, ink.amber)
        end
        if p.apply then
            ui:control('apply', x, b.status, '确认选择')
        end
        if p.all then
            ui:control('all', x + 14, b.status, '全选未分配')
        end
        if not p.clearRecipes then
            ui:control('back', x + 34, b.status, '返回')
        end
    elseif o and o.kind == 'box' then
        self:drawBox(o, x, width)
    elseif o and o.kind == 'fluids' then
        self:drawFluids(x, width, b)
    else
        local rows = self:form()
        self.offset = math.max(1, math.min(self.offset, math.max(1, #rows)))
        for i = self.offset, math.min(#rows, self.offset + self.perPage - 1) do
            local f = rows[i]
            local y = 6 + (i - self.offset) * stride
            if f.kind == 'heading' then
                local label = ui:clip(' ' .. f.label .. ' ', width - 2)
                ui:put(
                    x - 1,
                    y,
                    '├─' .. label .. string.rep('─', width - ui.u.wlen(label) - 1) .. '┤',
                    width + 2,
                    ink.green
                )
            elseif f.kind == 'action' then
                ui:control('field:' .. i, x, y, f.label, false, width)
            else
                local labelWidth = stride == 1 and math.floor(width / 2) or width
                ui:put(x, y, f.label, labelWidth, ink.text)
                local editing = self.edit and self.edit.field.index == i
                ui:control(
                    'field:' .. i,
                    stride == 1 and x + labelWidth or x,
                    stride == 1 and y or y + 1,
                    editing and self.edit.text .. '_' or self:value(f),
                    editing,
                    stride == 1 and width - labelWidth or width
                )
            end
        end
        if #rows == 0 then
            ui:put(x, 6, '请先添加配置，或按 F 刷新设备', width, ink.dim)
        end
        if self.edit then
            ui:control('confirm-edit', x, b.status, '确认')
            ui:control('cancel-edit', x + 10, b.status, '取消')
            ui:put(x + 20, b.status, '回车确认', width - 20, ink.dim)
        else
            ui:put(
                x,
                b.status,
                '方向：左键下一项，右键上一项；首尾循环',
                width,
                ink.dim
            )
        end
    end
    if self.popup and self.popup.clearRecipes then
        ui:wrap(
            2,
            h - 2,
            '确认后立即清除并保存；请选择取消或确认清除',
            w - 3,
            2,
            ink.amber
        )
    else
        ui:control('prev', x, b.nav, '上一页')
        ui:control('next', x + 12, b.nav, '下一页')
        ui:control('refresh', x + 24, b.nav, 'F 刷新')
        ui:wrap(2, h - 2, self.message, w - 3, 2, ink.amber)
        ui:control('save', 2, h, 'S 保存并返回')
        ui:control('quit', 22, h, 'Q 返回 / 保留暂存配置')
        ui:put(47, h, '↑↓对象 []翻页', w - 48, ink.dim)
    end
    ui:paint()
end

function F:run()
    self:draw()
    if self.ui:discardInput() then
        self:event('interrupted')
    end
    while not self.done do
        self:event(self.ui.event.pull())
        if not self.done then
            self:draw()
        end
    end
    return not not self.saved
end
return F
]=],
}
files[#files + 1] = {
    name = 'ma_gui.lua',
    code = [=[
-- Palette, split panels and changed-row painting follow maxwell-cache/bec_ui.lua.
local G = {}
G.__index = G
local ink = {
    bg = 0x101820,
    panel = 0x1C2936,
    selected = 0x263E50,
    text = 0xE1EAF0,
    dim = 0x91A4B5,
    cyan = 0x50D9DD,
    green = 0x78D6A1,
    amber = 0xFFD080,
    red = 0xFF8989,
}
G.ink = ink
local function exact(n)
    return n ~= nil and string.format('%.0f', n) or '--'
end

local function amount(n)
    if n == nil then
        return '--'
    end
    for _, v in ipairs({ { 1e15, 'P' }, { 1e12, 'T' }, { 1e9, 'G' }, { 1e6, 'M' }, { 1e3, 'k' } }) do
        if n >= v[1] then
            return string.format('~%.2f%s', n / v[1], v[2])
        end
    end
    return exact(n)
end
G.amount = amount
G.exact = exact
function G.new(gpu, event, unicode, config, materials)
    local self = setmetatable({
        gpu = gpu,
        event = event,
        u = unicode,
        C = config,
        M = materials,
        cache = {},
        tab = 1,
        selected = { 1, 1, 1 },
        arrayIndex = 1,
        nodePage = 1,
    }, G)
    local w, h = gpu.getResolution()
    if w < 80 or h < 25 then
        local mw, mh = gpu.maxResolution()
        gpu.setResolution(math.min(120, mw), math.min(38, mh))
    end
    self.w, self.h = gpu.getResolution()
    assert(
        self.w >= 80 and self.h >= 25,
        '中文配置需要至少 80×25 分辨率，请使用二级或三级显卡与屏幕'
    )
    return self
end

function G:clip(s, n)
    s = tostring(s or ''):gsub('§.', ''):gsub('[\r\n]', ' ')
    while self.u.wlen(s) > n and #s > 0 do
        s = self.u.sub(s, 1, self.u.len(s) - 1)
    end
    return s
end

function G:begin(title)
    self.w, self.h = self.gpu.getResolution()
    self.rows = {}
    self.hits = {}
    for y = 1, self.h do
        self.rows[y] = {}
    end
    self:put(1, 1, string.rep(' ', self.w), self.w, ink.cyan, ink.panel)
    self:put(2, 1, title, self.w - 3, ink.cyan, ink.panel)
end

function G:put(x, y, text, width, fg, bg)
    width = math.min(width or self.w - x + 1, self.w - x + 1)
    if y < 1 or y > self.h or x < 1 or width < 1 then
        return
    end
    self.rows[y][#self.rows[y] + 1] = { x, self:clip(text, width), fg or ink.text, bg or ink.bg }
end

function G:button(id, x, y, label, selected, width)
    local text = self:clip('[' .. label .. ']', width or self.w - x + 1)
    local n = self.u.wlen(text)
    self:put(x, y, text, n, selected and ink.bg or ink.cyan, selected and ink.cyan or ink.panel)
    self.hits[#self.hits + 1] = { id = id, x = x, y = y, w = n }
end

function G:control(id, x, y, label, selected, width)
    local text = self:clip(label, width or self.w - x + 1)
    local n = width or self.u.wlen(text)
    self:put(
        x,
        y,
        text .. string.rep(' ', math.max(0, n - self.u.wlen(text))),
        n,
        selected and ink.bg or ink.cyan,
        selected and ink.cyan or ink.panel
    )
    self.hits[#self.hits + 1] = { id = id, x = x, y = y, w = n }
end

function G:hit(x, y)
    for _, h in ipairs(self.hits) do
        if y == h.y and x >= h.x and x < h.x + h.w then
            return h.id
        end
    end
end

function G:discardInput()
    local interrupted = false
    while true do
        local name = self.event.pull(0)
        if not name then
            return interrupted
        end
        interrupted = interrupted or name == 'interrupted'
    end
end

function G:bar(x, y, width, ratio, color)
    self:put(x, y, string.rep('━', width), width, ink.panel)
    self:put(
        x,
        y,
        string.rep('━', math.floor(width * math.max(0, math.min(1, ratio or 0)))),
        width,
        color or ink.cyan
    )
end

function G:frame(x, top, width, bottom)
    self:put(x, top, '┌' .. string.rep('─', width - 2) .. '┐', width, ink.dim)
    for y = top + 1, bottom - 1 do
        self:put(x, y, '│', 1, ink.dim)
        self:put(x + width - 1, y, '│', 1, ink.dim)
    end
    self:put(x, bottom, '└' .. string.rep('─', width - 2) .. '┘', width, ink.dim)
end

function G:wrap(x, y, text, width, lines, color)
    text = tostring(text or ''):gsub('[\r\n]', ' ')
    for line = 0, lines - 1 do
        local part = self:clip(text, width)
        self:put(x, y + line, part, width, color)
        text = self.u.sub(text, self.u.len(part) + 1)
    end
end

function G:paint()
    local w, h = self.w, self.h
    if w ~= self.width or h ~= self.height then
        self.cache = {}
        self.width, self.height = w, h
    end
    local foreground, background
    local function colors(fg, bg)
        if fg ~= foreground then
            self.gpu.setForeground(fg)
            foreground = fg
        end
        if bg ~= background then
            self.gpu.setBackground(bg)
            background = bg
        end
    end
    for y, row in ipairs(self.rows) do
        local signature = {}
        for _, s in ipairs(row) do
            signature[#signature + 1] = table.concat(s, '\31')
        end
        signature = table.concat(signature, '\30')
        if self.cache[y] ~= signature then
            colors(ink.text, ink.bg)
            self.gpu.set(1, y, string.rep(' ', w))
            for _, s in ipairs(row) do
                colors(s[3], s[4])
                self.gpu.set(s[1], y, s[2])
            end
            self.cache[y] = signature
        end
    end
    colors(0xFFFFFF, 0x000000)
end

function G:recordName(cfg, section, value)
    local key = type(value) == 'table' and (value.id or value.address) or value
    for i, r in ipairs(cfg[section] or {}) do
        if r == value or key and (r.id == key or r.address == key) then
            if r.name and r.name ~= '' then
                return r.name
            end
            if section == 'channels' and #cfg[section] == 1 then
                return '公共原料子网'
            end
            if section == 'feeds' and #cfg[section] == 1 then
                return '预缓存设备'
            end
            local names = {
                arrays = '观测阵列',
                beePools = '蜂群池',
                channels = '接收子网',
                feeds = '预缓存设备',
                inventories = '元件容器连接',
            }
            return (names[section] or '配置') .. ' ' .. i
        end
    end
    return '未选择'
end

function G:choices(f, cfg, devices)
    local rows = {}
    if f.source:sub(1, 7) == 'device:' then
        for _, d in ipairs(devices) do
            if self.C.matches(d, f.source:sub(8)) then
                local names = {
                    me_controller = 'ME 控制器',
                    me_interface = 'ME 接口',
                    transposer = '转运器',
                    redstone = '红石 I/O',
                    bec_storage = '约束场',
                    bec_diode = '麦克斯韦门',
                    bec_io_node = '传送节点',
                }
                local machines = {
                    ['multi.bec.assembler'] = '观测阵列',
                    ['multi.bec.generator'] = '纠缠装置',
                }
                local detail = names[d.kind] or machines[d.name] or d.name or d.kind
                for _, a in ipairs(cfg.arrays) do
                    if a.diode == d.address then
                        detail = detail .. ' / ' .. self:recordName(cfg, 'arrays', a)
                    end
                end
                for _, c in ipairs(cfg.channels) do
                    if c.buffer == d.address then
                        detail = detail .. ' / ' .. self:recordName(cfg, 'channels', c)
                    end
                end
                rows[#rows + 1] = { label = d.address, value = d.address, detail = detail }
            end
        end
    else
        for _, x in ipairs(cfg[f.source]) do
            rows[#rows + 1] = { label = self:recordName(cfg, f.source, x), value = x.id }
        end
    end
    return rows
end

function G:edit(cfg, component, save)
    return self.Editor.new(self, cfg, component, save):run()
end
local phases = {
    admit = '节点取料',
    collect = '收集算力奇点',
    wait = '等待凝聚物或蜂群',
    run = '加工',
    ['return'] = '回收蜂群',
}

local function phase(b, s)
    if s and s.bee then
        return (s.bee.loading and '装载 T' or '回收 T') .. s.bee.tier .. ' 蜂群'
    end
    if s and s.request then
        return (s.request.supply and '等待补充 T' or '等待 T') .. s.request.tier .. ' 蜂群'
    end
    if b.phase == 'wait' and not b.granted then
        return '等待凝聚物'
    end
    return phases[b.phase]
end

function G:beeWait(e, a)
    local s = e.s.arrays[a.address]
    local request = s and s.request
    if not request then
        return
    end
    local count, owners = 0, {}
    for _, pool in ipairs(e.cfg.beePools) do
        if pool.id == a.beePool then
            for _, cell in ipairs(pool.cells) do
                if cell.tier == request.tier then
                    count = count + 1
                end
            end
        end
    end
    for _, other in ipairs(e.arrays) do
        local state = e.s.arrays[other.address]
        if other.beePool == a.beePool and state and state.lease and state.lease[request.tier] then
            owners[#owners + 1] = self:recordName(e.cfg, 'arrays', other)
        end
    end
    return 'T'
        .. request.tier
        .. ' 共登记 '
        .. count
        .. ' 套；'
        .. (
            #owners > 0 and '正在使用：' .. table.concat(owners, '、')
            or '当前无阵列借用'
        )
end

function G:runtime(e, refill)
    self:begin('BEC / 多观测阵列')
    local w, h = self.w, self.h
    local actions = {
        { 'quit', 'Q 完成后退出' },
        { 'setup', 'S 完成后配置' },
        { 'interrupt', 'Ctrl+C 暂停并保存' },
    }
    local actionWidth = 0
    for _, action in ipairs(actions) do
        actionWidth = actionWidth + self.u.wlen(action[2]) + 4
    end
    local actionX = w - actionWidth + 2
    for _, action in ipairs(actions) do
        self:button(action[1], actionX, 1, action[2])
        actionX = actionX + self.u.wlen(action[2]) + 4
    end
    local total, active, done = 0, 0, 0
    for _, n in pairs(e.stock or {}) do
        total = total + n
    end
    for _, a in ipairs(e.arrays) do
        local s = e.s.arrays[a.address]
        if s then
            done = done + (s.done or 0)
            if s.batch then
                active = active + 1
            end
        end
    end
    self:put(
        2,
        2,
        e.stopping and '正在完成已接订单并回收蜂群；可按 Ctrl+C 立即暂停'
            or e.ready and ''
            or '等待约束场完成当前周期',
        w - 3,
        ink.green
    )
    self:put(
        2,
        3,
        '阵列 '
            .. active
            .. ' / '
            .. #e.arrays
            .. '  |  排队 '
            .. #e.s.queue
            .. '  |  纠缠装置 '
            .. #e.cfg.generators
            .. '  |  已完成 '
            .. exact(done)
            .. ' 份',
        w - 3
    )
    self:put(
        2,
        4,
        '库存 ' .. amount(e.stock and total) .. ' / ' .. amount(e.cfg.fieldLimit) .. ' L',
        w - 3,
        ink.cyan
    )
    self:bar(2, 5, w - 12, total / e.cfg.fieldLimit)
    self:put(w - 9, 5, string.format('%.1f%%', 100 * total / e.cfg.fieldLimit), 8, ink.dim)
    for i, label in ipairs({ '1 库存', '2 阵列', '3 AE下单' }) do
        self:button('tab:' .. i, 2 + (i - 1) * 12, 7, label, self.tab == i)
    end
    self:put(40, 7, '~ 为约数', w - 41, ink.dim)
    local fluids, known = {}, {}
    for _, b in ipairs(e.cfg.bands) do
        for _, m in ipairs(e.M) do
            if b.material == m.source then
                fluids[#fluids + 1] = { id = m.condensate, band = b }
                known[m.condensate] = true
            end
        end
    end
    local extras = {}
    for id in pairs(e.stock or {}) do
        if not known[id] then
            extras[#extras + 1] = id
        end
    end
    table.sort(extras)
    for _, id in ipairs(extras) do
        fluids[#fluids + 1] = { id = id }
    end
    local channels = {}
    local precaching = {}
    local refillState = refill and refill.s
    for _, f in ipairs(e.cfg.feeds) do
        local s = refillState and refillState.feeds[f.id]
        if s then
            for i in pairs(s.pending) do
                precaching[f.cells[i].material] = true
            end
            if s.loading then
                precaching[f.cells[s.loading.index].material] = true
            end
        end
    end
    for _, c in ipairs(e.cfg.channels) do
        channels[#channels + 1] = {
            label = '接单：' .. self:recordName(e.cfg, 'channels', c),
            status = e.status[c.id] or '等待',
            error = e.errors[c.id],
        }
    end
    for _, f in ipairs(e.cfg.feeds) do
        channels[#channels + 1] = {
            label = '预缓存纠缠流体：' .. self:recordName(e.cfg, 'feeds', f),
            status = refill and refill.detail[f.id] or '等待',
        }
    end
    local list = self.tab == 1 and fluids or self.tab == 2 and e.arrays or channels
    self.count = #list
    self.perPage = math.max(1, h - 18)
    local selected = math.max(1, math.min(self.selected[self.tab], math.max(1, #list)))
    self.selected[self.tab] = selected
    if self.tab == 2 then
        self.arrayIndex = selected
    end
    self.arrayIndex = math.max(1, math.min(self.arrayIndex, math.max(1, #e.arrays)))
    local wide = w >= 120
    local left = wide and w - 49 or w - 2
    local page = math.floor((selected - 1) / self.perPage)
    local first = page * self.perPage + 1
    self:put(
        2,
        9,
        self.tab == 1 and '凝聚态简称 / L'
            or self.tab == 2 and '观测阵列 / 当前批次'
            or 'AE下单 / 状态',
        left,
        ink.dim
    )
    if self.tab == 1 then
        self:put(left - 38, 9, '现存', 12, ink.dim)
        self:put(left - 25, 9, '预缓存目标', 12, ink.dim)
        self:put(left - 12, 9, '状态', 12, ink.dim)
    end
    for i = first, math.min(#list, first + self.perPage - 1) do
        local y = 10 + i - first
        local bg = i == selected and ink.selected or ink.bg
        local r = list[i]
        self:put(2, y, string.rep(' ', left), left, ink.text, bg)
        self.hits[#self.hits + 1] = { id = 'row:' .. i, x = 2, y = y, w = left }
        local prefix = i == selected and '> ' or '  '
        if self.tab == 1 then
            local have = e.stock and (e.stock[r.id] or 0)
            local reserve = (e.reserved or {})[r.id] or 0
            local status = not have and '待读取'
                or have < reserve and '库存不足'
                or r.band and precaching[r.band.material] and '正在预缓存'
                or r.band and (have - reserve <= r.band.low or refillState and refillState.active[r.band.material]) and '等待预缓存'
                or '充足'
            self:put(2, y, prefix .. e.M.name(r.id, true), left - 42, ink.text, bg)
            self:put(left - 38, y, amount(have), 12, ink.cyan, bg)
            self:put(left - 25, y, amount(r.band and r.band.high), 12, ink.dim, bg)
            self:put(left - 12, y, status, 12, status == '充足' and ink.green or ink.amber, bg)
        elseif self.tab == 2 then
            local s = e.s.arrays[r.address]
            local b = s and s.batch
            local label = e.errors[r.address] and '已暂停'
                or b and phase(b, s)
                or e.status[r.address]
                or '空闲'
            self:put(2, y, prefix .. self:recordName(e.cfg, 'arrays', r), 19, ink.cyan, bg)
            self:put(
                22,
                y,
                label
                    .. (
                        b
                            and ' ×' .. b.count .. ' ' .. (b.collection and '算力奇点合并加工' or e.s.patterns[b.key].pattern.label)
                        or ''
                    ),
                left - 20,
                e.errors[r.address] and ink.red or ink.text,
                bg
            )
        else
            self:put(
                2,
                y,
                prefix .. r.label .. '  ' .. (r.error and '已暂停' or r.status),
                left,
                r.error and ink.red or ink.text,
                bg
            )
        end
    end
    self:put(
        2,
        h - 8,
        string.format(
            '%d / %d  第 %d/%d 页',
            #list > 0 and selected or 0,
            #list,
            page + 1,
            math.max(1, math.ceil(#list / self.perPage))
        ),
        left,
        ink.dim
    )
    local row = list[selected]
    if row then
        if self.tab == 1 then
            self:put(2, h - 5, e.M.name(row.id), w - 3, ink.cyan)
            self:put(
                2,
                h - 4,
                '现存 '
                    .. exact(e.stock and (e.stock[row.id] or 0))
                    .. ' L  已预留 '
                    .. exact((e.reserved or {})[row.id] or 0)
                    .. ' L',
                w - 3
            )
            self:put(
                2,
                h - 3,
                row.band
                        and '下限 ' .. exact(row.band.low) .. ' / 目标 ' .. exact(row.band.high) .. ' L'
                    or '未设置预缓存',
                w - 3,
                ink.dim
            )
        elseif self.tab == 2 then
            local s = e.s.arrays[row.address]
            local b = s and s.batch
            self:put(2, h - 5, row.address, w - 3, ink.cyan)
            self:wrap(
                2,
                h - 4,
                e.errors[row.address]
                    or e.status[row.address]
                    or b and phase(b, s)
                    or '等待分配订单',
                w - 3,
                2,
                e.errors[row.address] and ink.red or ink.text
            )
            if not e.errors[row.address] then
                local leases = {}
                for tier = 1, 10 do
                    local c = s and s.lease and s.lease[tier]
                    if c then
                        leases[#leases + 1] = 'T' .. tier .. ' 箱' .. c.box .. ' 槽' .. c.slot
                    end
                end
                local tier = (e.provided or {})[row.address]
                self:put(
                    2,
                    h - 3,
                    self:beeWait(e, row)
                        or self:recordName(e.cfg, 'beePools', row.beePool)
                            .. ' / '
                            .. (tier and '已装载 T' .. tier or '未装载蜂群')
                            .. ' / '
                            .. (#leases > 0 and table.concat(leases, '，') or '未借用')
                            .. (s and s.request and ' / 等待 T' .. s.request.tier or ''),
                    w - 3,
                    ink.dim
                )
            end
        else
            self:put(2, h - 5, row.label, w - 3, ink.cyan)
            self:wrap(
                2,
                h - 4,
                row.error or row.status,
                w - 3,
                2,
                row.error and ink.red or ink.text
            )
        end
    end
    if wide then
        self:arrayPanel(e, left + 4, 9, 45, h - 8)
    elseif self.tab == 2 then
        self:button(
            'nodes',
            w - 18,
            7,
            self.nodeOnly and '返回阵列' or '查看节点',
            self.nodeOnly
        )
        if self.nodeOnly then
            for y = 9, h - 6 do
                self.rows[y] = {}
            end
            -- Remove covered row hitboxes before drawing the node panel.
            local hits = {}
            for _, hit in ipairs(self.hits) do
                if hit.y < 9 or hit.y > h - 6 then
                    hits[#hits + 1] = hit
                end
            end
            self.hits = hits
            self:arrayPanel(e, 2, 9, w - 3, h - 8)
        end
    end
    self:frame(1, 8, left + 2, h - 7)
    if wide then
        self:frame(left + 3, 8, w - left - 2, h - 7)
    end
    self:frame(1, h - 6, w, h - 2)
    self:button('prev', 2, h, '上一页')
    self:button('next', 12, h, '下一页')
    self:put(23, h, '1/2/3 面板  ↑↓选择  []翻页', w - 24, ink.cyan)
    self:paint()
end

function G:arrayPanel(e, x, top, width, bottom)
    local a = e.arrays[self.arrayIndex]
    if not a then
        return
    end
    local s = e.s.arrays[a.address]
    local b = s and s.batch
    self:put(
        x,
        top,
        self:recordName(e.cfg, 'arrays', a) .. '  ' .. a.address:sub(1, 12),
        width,
        ink.cyan
    )
    self:button('array-', x, top + 1, '上一台')
    self:button('array+', x + 10, top + 1, '下一台')
    self:put(
        x,
        top + 3,
        e.errors[a.address] and '已暂停 / 暂停前进度'
            or b and phase(b, s) .. ' ×' .. b.count
            or e.status[a.address]
            or '等待 AE 下单',
        width,
        e.errors[a.address] and ink.red or ink.green
    )
    self:put(
        x,
        top + 4,
        s and s.bee and '蜂群 T' .. s.bee.tier .. (s.bee.loading and ' 装载中' or ' 回收中')
            or '节点 / 并行 / 所需蜂群 / 进度',
        width,
        ink.dim
    )
    local observed = (e.observations or {})[a.address]
    local views, workers = {}, {}
    for _, n in pairs(observed or {}) do
        views[n.address] = n
    end
    for _, worker in ipairs(b and b.workers or {}) do
        workers[worker.address] = worker
    end
    local per = math.max(1, bottom - top - 5)
    self.nodePages = math.max(1, math.ceil(#a.nodes / per))
    self.nodePage = math.max(1, math.min(self.nodePage, self.nodePages))
    for i = (self.nodePage - 1) * per + 1, math.min(#a.nodes, self.nodePage * per) do
        local y = top + 5 + i - (self.nodePage - 1) * per - 1
        local address = a.nodes[i].address
        local n = views[address]
        local worker = workers[address]
        if b and b.phase == 'run' and n then
            self:put(
                x,
                y,
                '#' .. i .. '  ' .. exact(n.parallel) .. ' 并行  T' .. (n.tier or '-'),
                width - 9
            )
            self:put(
                x + width - 8,
                y,
                n.fast and '固定蜂群'
                    or string.format('%5.1f%%', 100 * math.min(1, n.progress / n.length)),
                8,
                ink.cyan
            )
        else
            local status = '空闲'
            if worker then
                if b.phase == 'run' then
                    status = observed and '本批完成' or '待读取'
                else
                    local cached = (e.nodeCache or {})[address]
                    local accepted = b.phase ~= 'admit'
                        or worker.accepted
                        or cached and cached.worker == worker and cached.accepted
                    status = (accepted and '已取料 ' or '待取料 ') .. worker.count .. ' 份'
                end
            end
            self:put(x, y, '#' .. i .. '  ' .. status, width, ink.dim)
        end
    end
    self:button('node-', x, bottom, '上页')
    self:button('node+', x + 8, bottom, '下页')
    self:put(
        x + 16,
        bottom,
        '节点 ' .. self.nodePage .. '/' .. self.nodePages,
        width - 16,
        ink.dim
    )
end

function G:runtimeEvent(name, _, ch, code, direction)
    local action = name == 'touch' and self:hit(ch, code)
    if name == 'key_down' then
        if ch == 115 or ch == 83 then
            return 'setup'
        elseif ch == 113 or ch == 81 then
            return 'quit'
        elseif ch and ch >= 49 and ch <= 51 then
            action = 'tab:' .. (ch - 48)
        elseif code == 15 then
            action = 'tab:' .. (self.tab % 3 + 1)
        elseif code == 200 then
            action = 'up'
        elseif code == 208 then
            action = 'down'
        elseif code == 201 or ch == 91 then
            action = 'prev'
        elseif code == 209 or ch == 93 then
            action = 'next'
        end
    elseif name == 'scroll' then
        action = direction > 0 and 'up' or 'down'
    elseif name == 'interrupted' then
        return 'interrupt'
    end
    if not action then
        return
    end
    if action == 'setup' or action == 'quit' or action == 'interrupt' then
        return action
    end
    if action:match('^tab:') then
        self.tab = tonumber(action:sub(5))
        self.nodeOnly = false
    elseif action:match('^row:') then
        self.selected[self.tab] = tonumber(action:sub(5))
        self.nodePage = 1
    elseif action == 'up' or action == 'down' or action == 'prev' or action == 'next' then
        local step = (action == 'prev' or action == 'next') and self.perPage or 1
        local sign = (action == 'up' or action == 'prev') and -1 or 1
        self.selected[self.tab] = math.max(
            1,
            math.min(math.max(1, self.count or 0), self.selected[self.tab] + sign * step)
        )
        self.nodePage = 1
    elseif action == 'array-' or action == 'array+' then
        self.arrayIndex = math.max(1, self.arrayIndex + (action == 'array-' and -1 or 1))
        self.nodePage = 1
        if self.tab == 2 then
            self.selected[2] = self.arrayIndex
        end
    elseif action == 'node-' or action == 'node+' then
        self.nodePage =
            math.max(1, math.min(self.nodePages, self.nodePage + (action == 'node-' and -1 or 1)))
    elseif action == 'nodes' then
        self.nodeOnly = not self.nodeOnly
    end
    return 'redraw'
end
return G
]=],
}
files[#files + 1] = {
    name = 'ma_intake.lua',
    code = [=[
-- Solid-only AE orders. Replenishment has its own isolated fluid network.
-- No machine may consume from the receiver until its admission gate has closed.
local I = {}
function I.key(s)
    local tag = ''
    if s.hasTag then
        assert(
            s.tag,
            '无法读取物品 NBT 数据，请启用 OC 的物品 NBT 访问或使用无标签原料'
        )
        tag = s.tag
    end
    return 'i:' .. #s.name .. ':' .. s.name .. ':' .. tostring(s.damage or 0) .. ':' .. tag
end

function I.amount(s, fluid)
    return fluid and (s.amount or s.size) or s.size
end

function I.inventory(items)
    local counts = {}
    for _, s in pairs(items) do
        local n = I.amount(s)
        if n > 0 then
            local key = I.key(s)
            counts[key] = (counts[key] or 0) + n
            assert(counts[key] <= 9007199254740991, '库存数量过大，OC 无法准确计数')
        end
    end
    return counts
end

local function subset(a, b)
    for key in pairs(a) do
        if not b[key] then
            return false
        end
    end
    return true
end

local function identity(counts)
    local keys, parts = {}, {}
    for key in pairs(counts) do
        keys[#keys + 1] = key
    end
    table.sort(keys)
    for _, key in ipairs(keys) do
        parts[#parts + 1] = #key .. ':' .. key .. '=' .. counts[key]
    end
    return table.concat(parts, ';')
end
-- Only the fifteen BEC computation singularities; the base singularity is not included.
function I.singularity(outputs)
    local key = next(outputs)
    if not key or next(outputs, key) then
        return
    end
    for tier = 0, 14 do
        local name = tier < 10 and 'universalsingularities:universal.circuit.singularity'
            or 'universalsingularities:universal.circuit2.singularity'
        if key == I.key({ name = name, damage = tier < 10 and tier or tier - 10 }) then
            return tier + 1
        end
    end
end

function I.catalog(patterns)
    local result = { patterns = {} }
    for slot, p in pairs(patterns) do
        assert(p.isCraftable == false, '请将槽位 ' .. slot .. ' 中的样板设为处理样板')
        local entry = { slot = slot, inputs = {}, outputs = {} }
        for _, s in pairs(p.inputs) do
            if s.name then
                assert(
                    not s.name:lower():find('pattern', 1, true)
                        and not s.name:lower():find('packet', 1, true),
                    '处理样板的输入只能包含固体原料，不能包含样板或流体'
                )
                local fluid = s.amount ~= nil and s.damage == nil
                local n = I.amount(s, fluid)
                if n > 0 then
                    assert(
                        not fluid,
                        '处理样板的输入只能包含固体原料，请删除流体输入'
                    )
                    local key = I.key(s)
                    entry.inputs[key] = (entry.inputs[key] or 0) + n
                end
            end
        end
        assert(next(entry.inputs), '槽位 ' .. slot .. ' 中的样板未填写固体原料')

        for _, s in pairs(p.outputs) do
            if s.name and I.amount(s, s.amount ~= nil and s.damage == nil) > 0 then
                assert(s.damage ~= nil, '处理样板的输出必须是物品')
                local key = I.key(s)
                entry.outputs[key] = (entry.outputs[key] or 0) + I.amount(s, false)
                entry.label = entry.label or s.label or s.name
            end
        end
        assert(next(entry.outputs), '处理样板未填写物品输出')
        entry.singularity = I.singularity(entry.outputs)
        local inputs = identity(entry.inputs)
        entry.key = #inputs .. ':' .. inputs .. identity(entry.outputs)
        for _, other in ipairs(result.patterns) do
            assert(
                not subset(entry.inputs, other.inputs) and not subset(other.inputs, entry.inputs),
                '无法区分槽位 '
                    .. slot
                    .. ' 与 '
                    .. other.slot
                    .. ' 的样板；公共原料子网无法区分这些原料，请删除或调整冲突样板'
            )
        end
        result.patterns[#result.patterns + 1] = entry
    end
    assert(#result.patterns > 0, '配置的样板接口中没有处理样板')
    return result
end

function I.identify(catalog, counts)
    if not next(counts) then
        return nil
    end
    local partial
    for _, p in ipairs(catalog.patterns) do
        local compatible = true
        for key, n in pairs(counts) do
            if n > 0 and not p.inputs[key] then
                compatible = false
                break
            end
        end
        if compatible then
            partial = true
            local ready = true
            for key in pairs(p.inputs) do
                if (counts[key] or 0) == 0 then
                    ready = false
                    break
                end
            end
            if ready then
                return p
            end
        end
    end
    assert(
        partial,
        '公共原料子网中有无法识别或混入其他配方的原料，已停止接单；请核对原料和处理样板'
    )
end
-- A stopped admission gate leaves k complete vectors plus at most one partial vector.
-- The largest ceil(r_i/v_i) includes that accepted partial delivery; floor-min is ready now.
function I.receipts(pattern, counts)
    local admitted, complete = 0, math.huge
    for key, n in pairs(counts) do
        assert(n == 0 or pattern.inputs[key], '已接订单中出现无法识别的原料')
    end
    for key, need in pairs(pattern.inputs) do
        local n = counts[key] or 0
        admitted = math.max(admitted, math.ceil(n / need))
        complete = math.min(complete, math.floor(n / need))
    end
    assert(
        admitted >= 1 and admitted <= 2147483647,
        '一单最多支持 2147483647 份配方，请分单下单'
    )
    assert(
        complete >= admitted - 1,
        '多份配方原料未到齐，接收库存可能被提前抽取或发生混料'
    )
    return admitted, complete
end
return I
]=],
}
files[#files + 1] = {
    name = 'ma_logistics.lua',
    code = [=[
-- Direct cell transfers. Keep both slots reserved until the move is acknowledged.
local L = {}
L.__index = L
function L.new(cfg, state, proxy, save, U)
    state.moves = state.moves or {}
    return setmetatable({
        state = state,
        proxy = proxy,
        save = save,
        inventories = U.index(cfg.inventories),
    }, L)
end

function L:stack(id, slot)
    local e = assert(self.inventories[id], '未配置元件容器连接：' .. tostring(id))
    return self.proxy(e.transposer).getStackInSlot(e.side, slot)
end

function L:size(id)
    local e = assert(self.inventories[id])
    return assert(
        self.proxy(e.transposer).getInventorySize(e.side),
        '无法读取元件容器，请检查转运器方向和连接：' .. id
    )
end

local function key(id, slot)
    return id .. ':' .. slot
end

function L:locks()
    local locks = {}
    for owner, m in pairs(self.state.moves) do
        for k in pairs(m.locks) do
            locks[k] = owner
        end
    end
    return locks
end

function L:start(owner, from, to, sourceSlot, targetSlot, ioSink)
    if self.state.moves[owner] then
        return true
    end
    local locks = { [key(from, sourceSlot)] = true, [key(to, targetSlot)] = true }
    if ioSink then
        locks[key(to, 7)] = true
    end
    local occupied = self:locks()
    for k in pairs(locks) do
        if occupied[k] then
            return false
        end
    end
    if self:stack(to, targetSlot) then
        return false
    end
    self.state.moves[owner] = {
        from = from,
        to = to,
        fromSlot = sourceSlot,
        toSlot = targetSlot,
        locks = locks,
        ioSink = ioSink,
    }
    return true
end

function L:tick(owner)
    local m = assert(self.state.moves[owner])
    if m.done then
        return true
    end
    local source, target = self:stack(m.from, m.fromSlot), self:stack(m.to, m.toSlot)
    if not m.intent then
        assert(
            source and not target,
            '元件位置与搬运记录不一致，请检查是否被手动移动：' .. owner
        )
        m.intent = true
        self.save()
    end
    if source then
        assert(not target, '目标槽位已被占用：' .. m.to .. ':' .. m.toSlot)
        local from, to = self.inventories[m.from], self.inventories[m.to]
        local n, err = self.proxy(from.transposer)
            .transferItem(from.side, to.side, 1, m.fromSlot, m.toSlot)
        assert(n ~= nil, err or '元件搬运失败')
        if n == 0 then
            return false
        end
    else
        assert(
            target or (m.ioSink and self:stack(m.to, 7)),
            '找不到正在搬运的元件：' .. owner
        )
    end
    m.intent = nil
    m.done = true
    return m.done
end

function L:finish(owner)
    self.state.moves[owner] = nil
    self.save()
end

function L:step(owner, from, to, sourceSlot, targetSlot, ioSink)
    if not self:start(owner, from, to, sourceSlot, targetSlot, ioSink) then
        return false
    end
    return self:tick(owner)
end
return L
]=],
}
