-- A rename commits a complete serialized snapshot on the same OpenOS filesystem.
local S = {}
function S.new(base, fs, serialization, yield)
    local self = {}
    function self.read(name)
        local f = io.open(base .. name, 'r')
        if not f then
            return nil
        end
        local data = f:read('*a')
        f:close()
        return assert(serialization.unserialize(data), '无法读取 ' .. name)
    end
    function self.write(name, value)
        local path = base .. name
        local f = assert(io.open(path .. '.tmp', 'w'))
        local buffer, bytes, seen = {}, 0, {}
        local function flush()
            if #buffer > 0 then
                assert(f:write(table.concat(buffer)))
                buffer, bytes = {}, 0
            end
            if yield then
                yield()
            end
        end
        local function put(text)
            buffer[#buffer + 1] = text
            bytes = bytes + #text
            if bytes >= 4096 or #buffer >= 256 then
                flush()
            end
        end
        local function encode(v)
            if type(v) == 'table' then
                assert(not seen[v], '不能保存包含循环引用的状态')
                seen[v] = true
                put('{')
                local index = 1
                for k, item in pairs(v) do
                    if k == index then
                        index = index + 1
                    else
                        put('[')
                        encode(k)
                        put(']=')
                    end
                    encode(item)
                    put(',')
                end
                put('}')
                seen[v] = nil
            elseif type(v) == 'string' then
                put('"')
                -- Short chunks avoid OC's expensive long-string pattern implementation.
                for i = 1, #v, 128 do
                    put((v:sub(i, i + 127):gsub('[%z\1-\31\\"]', function(c)
                        return string.format('\\%03d', c:byte())
                    end)))
                end
                put('"')
            elseif type(v) == 'number' and v == v and math.abs(v) < math.huge then
                put(string.format('%.17g', v))
            else
                put(serialization.serialize(v))
            end
        end
        local ok, err = pcall(function()
            encode(value)
            flush()
            assert(f:flush())
        end)
        local closed, closeErr = f:close()
        assert(ok, err)
        -- OpenOS close succeeds without returning a value.
        assert(closed ~= false and closeErr == nil, closeErr)
        assert(fs.rename(path .. '.tmp', path), '无法保存 ' .. name)
    end
    function self.clearRecipes()
        local state = self.read('multi.state') or {}
        assert(
            not state.admission and #(state.queue or {}) == 0,
            '仍有待完成订单，请先运行程序并按 Q 完成后退出'
        )
        for _, a in pairs(state.arrays or {}) do
            assert(
                not a.batch and not a.lease and not a.bee,
                '仍有加工或蜂群任务，请先运行程序并按 Q 完成后退出'
            )
        end
        local count = 0
        for _, p in pairs(state.patterns or {}) do
            if p.unit or p.steps then
                p.unit, p.steps = nil, nil
                count = count + 1
            end
        end
        if count > 0 then
            self.write('multi.state', state)
        end
        return count, state.patterns or {}
    end
    return self
end
return S
]=],
}
files[#files + 1] = {
    name = 'ma_util.lua',
    code = [=[
local U = {}
function U.copy(v)
    if type(v) ~= 'table' then
        return v
    end
    local r = {}
    for k, x in pairs(v) do
        r[k] = U.copy(x)
    end
    return r
end

function U.equal(a, b)
    if type(a) ~= type(b) then
        return false
    end
    if type(a) ~= 'table' then
        return a == b
    end
    for k, v in pairs(a) do
        if not U.equal(v, b[k]) then
            return false
        end
    end
    for k in pairs(b) do
        if a[k] == nil then
            return false
        end
    end
    return true
end

function U.integer(n, lo, hi)
    return type(n) == 'number'
        and n == math.floor(n)
        and n >= (lo or 0)
        and n <= (hi or 9007199254740991)
end

function U.add(a, b, m)
    for k, v in pairs(b or {}) do
        a[k] = (a[k] or 0) + v * (m or 1)
        assert(a[k] <= 9007199254740991, '数量过大，OC 无法准确计数：' .. k)
    end
    return a
end

function U.total(a)
    local n = 0
    for _, v in pairs(a or {}) do
        n = n + v
    end
    assert(n <= 9007199254740991, '总量过大，OC 无法准确计数')
    return n
end

function U.fits(stock, need)
    for k, v in pairs(need or {}) do
        if (stock[k] or 0) < v then
            return false
        end
    end
    return true
end

function U.scale(a, n)
    return U.add({}, a, n)
end

function U.keys(t)
    local r = {}
    for k in pairs(t) do
        r[#r + 1] = k
    end
    table.sort(r)
    return r
end

function U.index(list, key)
    local r = {}
    for _, v in ipairs(list or {}) do
        r[v[key or 'id']] = v
    end
    return r
end
return U
]=],
}
